// Generated by `npm run toolkits:sync` in the CMS repository (toolkits/client). Do not edit here.
import type { Media } from "./types";

// <img> attributes from a media value, so every toolkit renders images the same
// way: the CMS srcset (WebP at the project's widths), intrinsic width/height
// (no layout shift), lazy by default, eager + high priority for the first image.

export type ImageOptions = {
  /** The `sizes` attribute; default: the full viewport. */
  sizes?: string;
  /** The first image of the page: eager, fetchpriority="high", decoding="sync". */
  priority?: boolean;
  /** Overrides the asset's alt text (an empty string marks a decorative image). */
  alt?: string;
  /** Request this width from the CMS for `src` (one of the project's widths); default: the optimized file. */
  width?: number;
  /** Paint the dominant color behind the image while it loads. Default: only for JPEGs, which have no transparency. */
  placeholder?: boolean;
};

export type ImageAttrs = {
  src: string;
  srcset?: string;
  sizes?: string;
  width?: number;
  height?: number;
  alt: string;
  loading: "eager" | "lazy";
  decoding: "sync" | "async";
  fetchpriority?: "high";
  /** Inline style painting the dominant color until the image arrives (no overlay, just the box). */
  style?: string;
};

/** Raster images get a srcset; SVGs and GIFs are served as they are. */
export const isRaster = (media: Pick<Media, "mime">) => media.mime.startsWith("image/") && media.mime !== "image/svg+xml" && media.mime !== "image/gif";

/** The CMS URL of one sized WebP variant of an image (`?w=640&f=webp`). */
export function variantUrl(media: Pick<Media, "url">, width: number) {
  const url = new URL(media.url);
  url.searchParams.set("w", String(width));
  url.searchParams.set("f", "webp");
  return url.toString();
}

export function imageAttrs(media: Media, options: ImageOptions = {}): ImageAttrs {
  const raster = isRaster(media);
  const width = media.optimized?.width ?? media.width ?? undefined;
  const height = media.optimized?.height ?? media.height ?? undefined;
  const attrs: ImageAttrs = {
    src: raster && options.width ? variantUrl(media, options.width) : media.url,
    alt: options.alt ?? media.alt ?? "",
    loading: options.priority ? "eager" : "lazy",
    decoding: options.priority ? "sync" : "async",
  };
  if (width && height) {
    attrs.width = width;
    attrs.height = height;
  }
  if (raster && media.srcset) {
    attrs.srcset = media.srcset;
    attrs.sizes = options.sizes ?? "100vw";
  }
  if (options.priority) attrs.fetchpriority = "high";
  // A PNG, WebP or GIF may be transparent: a dark box behind a logo is worse than no placeholder.
  if (media.dominantColor && (options.placeholder ?? media.mime === "image/jpeg")) attrs.style = `background-color:${media.dominantColor}`;
  return attrs;
}

/** The `sizes` value of an image that fills its column up to a maximum width (`"(min-width: 1200px) 1200px, 100vw"`). */
export const sizesUpTo = (maxWidth: number) => `(min-width: ${maxWidth}px) ${maxWidth}px, 100vw`;
